#!/usr/bin/env bash
# Host SQLite CLI. No dependency on the application image.
sqlite_verify() {
  test -s "$1" &&
    test "$(sqlite3 -batch -bail -readonly -cmd '.timeout 15000' "$1" 'PRAGMA integrity_check;')" = ok &&
    sqlite3 -batch -bail -readonly "$1" 'SELECT COUNT(*) FROM kv; SELECT COUNT(*) FROM diary_days;' >/dev/null
}

sqlite_snapshot() {
  local source=$1 destination=$2 staging
  test -s "$source" || return 1
  staging=$(mktemp -- "$destination.part.XXXXXX") || return 1
  # Double quotes are part of the SQLite shell dot command. Paths here are generated by the caller.
  if sqlite3 -batch -bail -cmd '.timeout 15000' "$source" ".backup \"$staging\"" &&
    sqlite_verify "$staging" && mv -f -- "$staging" "$destination"; then
    return 0
  fi
  rm -f -- "$staging"
  return 1
}
